  exitCode: number;
  stdout: string;
  stderr: string;
  json: any;
}

async function workspace(): Promise<{ directory: string; file: string }> {
  const directory = await mkdtemp(join(tmpdir(), "taskboard-test-"));
  directories.push(directory);
  return { directory, file: join(directory, "tasks.json") };
}

async function run(file: string, ...args: string[]): Promise<Result> {
  const process = Bun.spawn(["bun", "run", cli, ...args], {
    env: { ...Bun.env, TASKBOARD_FILE: file },
    stdout: "pipe",
    stderr: "pipe",
  });
  const [stdout, stderr, exitCode] = await Promise.all([
    new Response(process.stdout).text(),
    new Response(process.stderr).text(),
    process.exited,
  ]);
  return { exitCode, stdout, stderr, json: JSON.parse(stdout) };
}

