    expect((await run(file, "list", "--overdue", "2000-01-02")).json.map((task: any) => task.id)).toEqual([1]);

    const done = await run(file, "done", "1");
    const repeated = await run(file, "done", "1");
    expect(done.json.status).toBe("done");
    expect(repeated.json.completedAt).toBe(done.json.completedAt);

