#!/usr/bin/env bun

import { open, readFile, rename, unlink } from "node:fs/promises";
import { basename, dirname, join, resolve } from "node:path";

type Status = "open" | "done";

interface Task {
  id: number;
  title: string;
  status: Status;
  tags: string[];
  due?: string;
  createdAt: string;
  completedAt?: string;
}

interface Database {
  version: 1;
  nextId: number;
  tasks: Task[];
}

class CliError extends Error {}

const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;

function fail(message: string): never {
  throw new CliError(message);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isIsoTimestamp(value: unknown): value is string {
  return (
    typeof value === "string" &&
    !Number.isNaN(Date.parse(value)) &&
    new Date(value).toISOString() === value
  );
}

function isValidDate(value: unknown): value is string {
  if (typeof value !== "string") return false;
  const match = DATE_PATTERN.exec(value);
  if (!match) return false;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(Date.UTC(year, month - 1, day));

  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

function normalizeTag(tag: string): string {
  return tag.trim().toLowerCase();
}

function normalizeTags(value: string): string[] {
  const tags: string[] = [];
  const seen = new Set<string>();
  for (const rawTag of value.split(",")) {
    const tag = normalizeTag(rawTag);
    if (tag && !seen.has(tag)) {
      tags.push(tag);
      seen.add(tag);
    }
  }
  return tags;
}

function validateTask(value: unknown): value is Task {
  if (!isRecord(value)) return false;
  const keys = Object.keys(value);
  const allowed = new Set([
    "id",
    "title",
    "status",
    "tags",
    "due",
    "createdAt",
    "completedAt",
  ]);
  if (keys.some((key) => !allowed.has(key))) return false;
  if (!Number.isSafeInteger(value.id) || (value.id as number) < 1) return false;
  if (typeof value.title !== "string" || value.title.trim() === "") return false;
  if (value.status !== "open" && value.status !== "done") return false;
  if (!Array.isArray(value.tags)) return false;
  if (
    value.tags.some(
      (tag) =>
        typeof tag !== "string" ||
        tag === "" ||
        tag !== normalizeTag(tag),
    )
  ) {
    return false;
  }
  if (new Set(value.tags).size !== value.tags.length) return false;
  if (value.due !== undefined && !isValidDate(value.due)) return false;
  if (!isIsoTimestamp(value.createdAt)) return false;
  if (value.completedAt !== undefined && !isIsoTimestamp(value.completedAt)) {
    return false;
  }
  if (value.status === "open" && value.completedAt !== undefined) return false;
  if (value.status === "done" && value.completedAt === undefined) return false;
  return true;
}

function validateDatabase(value: unknown): Database {
  if (!isRecord(value)) fail("Malformed taskboard database");
  if (
    Object.keys(value).some(
      (key) => !["version", "nextId", "tasks"].includes(key),
    ) ||
    value.version !== 1 ||
    !Number.isSafeInteger(value.nextId) ||
    (value.nextId as number) < 1 ||
    !Array.isArray(value.tasks) ||
    !value.tasks.every(validateTask)
  ) {
    fail("Malformed taskboard database");
  }

  const database = value as unknown as Database;
  const ids = database.tasks.map((task) => task.id);
  if (
    new Set(ids).size !== ids.length ||
    ids.some((id) => id >= database.nextId)
  ) {
    fail("Malformed taskboard database");
  }
  return database;
}

async function loadDatabase(file: string): Promise<Database> {
  let contents: string;
  try {
    contents = await readFile(file, "utf8");
  } catch (error) {
    if (isRecord(error) && error.code === "ENOENT") {
      return { version: 1, nextId: 1, tasks: [] };
    }
    throw error;
  }

  try {
    return validateDatabase(JSON.parse(contents));
  } catch (error) {
    if (error instanceof CliError) throw error;
    fail("Malformed taskboard database");
  }
}

async function saveDatabase(file: string, database: Database): Promise<void> {
  const directory = dirname(file);
  const temporary = join(
    directory,
    `.${basename(file)}.${process.pid}.${crypto.randomUUID()}.tmp`,
  );
  let handle: Awaited<ReturnType<typeof open>> | undefined;

  try {
    handle = await open(temporary, "wx", 0o600);
    await handle.writeFile(`${JSON.stringify(database, null, 2)}\n`, "utf8");
    await handle.sync();
    await handle.close();
    handle = undefined;
    await rename(temporary, file);
  } catch (error) {
    await handle?.close().catch(() => undefined);
    await unlink(temporary).catch(() => undefined);
    throw error;
  }
}

interface ParsedOptions {
  values: Record<string, string>;
  positionals: string[];
}

function parseOptions(
  args: string[],
  allowed: ReadonlySet<string>,
): ParsedOptions {
  const values: Record<string, string> = {};
  const positionals: string[] = [];

  for (let index = 0; index < args.length; index += 1) {
    const argument = args[index];
    if (!argument.startsWith("--")) {
      positionals.push(argument);
      continue;
    }
    if (!allowed.has(argument)) fail(`Unknown flag: ${argument}`);
    if (argument in values) fail(`Duplicate flag: ${argument}`);
    const value = args[index + 1];
    if (value === undefined || value.startsWith("--")) {
      fail(`Missing value for ${argument}`);
    }
    values[argument] = value;
    index += 1;
  }
  return { values, positionals };
}

function parseId(value: string | undefined): number {
  if (value === undefined || !/^[1-9]\d*$/.test(value)) {
    fail("ID must be a positive integer");
  }
  const id = Number(value);
  if (!Number.isSafeInteger(id)) fail("ID must be a positive integer");
  return id;
}

function requireNoArguments(command: string, args: string[]): void {
  if (args.length > 0) {
    const unknown = args.find((argument) => argument.startsWith("--"));
    if (unknown) fail(`Unknown flag: ${unknown}`);
    fail(`${command} does not accept arguments`);
  }
}

function localDate(today = new Date()): string {
  const year = today.getFullYear();
  const month = String(today.getMonth() + 1).padStart(2, "0");
  const day = String(today.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

async function execute(args: string[], file: string): Promise<unknown> {
  const [command, ...rest] = args;
  if (!command) fail("Missing command");

  if (command === "add") {
    const parsed = parseOptions(
      rest,
      new Set(["--title", "--tags", "--due"]),
    );
    if (parsed.positionals.length > 0) fail("add does not accept positional arguments");
    const title = parsed.values["--title"];
    if (title === undefined) fail("Missing required flag: --title");
    if (title.trim() === "") fail("Title must not be empty");
    const due = parsed.values["--due"];
    if (due !== undefined && !isValidDate(due)) fail("Invalid due date");

    const database = await loadDatabase(file);
    const task: Task = {
      id: database.nextId,
      title,
      status: "open",
      tags: normalizeTags(parsed.values["--tags"] ?? ""),
      ...(due === undefined ? {} : { due }),
      createdAt: new Date().toISOString(),
    };
    database.nextId += 1;
    database.tasks.push(task);
    await saveDatabase(file, database);
    return task;
  }

  if (command === "list") {
    const parsed = parseOptions(
      rest,
      new Set(["--status", "--tag", "--overdue"]),
    );
    if (parsed.positionals.length > 0) fail("list does not accept positional arguments");
    const status = parsed.values["--status"];
    if (status !== undefined && status !== "open" && status !== "done") {
      fail("Status must be open or done");
    }
    const overdue = parsed.values["--overdue"];
    if (overdue !== undefined && !isValidDate(overdue)) fail("Invalid overdue date");
    const tag = parsed.values["--tag"];
    if (tag !== undefined && normalizeTag(tag) === "") fail("Tag must not be empty");

    const database = await loadDatabase(file);
    return database.tasks
      .filter((task) => status === undefined || task.status === status)
      .filter(
        (task) => tag === undefined || task.tags.includes(normalizeTag(tag)),
      )
      .filter(
        (task) =>
          overdue === undefined ||
          (task.status === "open" && task.due !== undefined && task.due < overdue),
      )
      .sort((left, right) => left.id - right.id);
  }

  if (command === "done") {
    const parsed = parseOptions(rest, new Set());
    if (parsed.positionals.length !== 1) fail("done requires exactly one ID");
    const id = parseId(parsed.positionals[0]);
    const database = await loadDatabase(file);
    const task = database.tasks.find((candidate) => candidate.id === id);
    if (!task) fail(`Task ${id} not found`);
    if (task.status === "open") {
      task.status = "done";
      task.completedAt = new Date().toISOString();
      await saveDatabase(file, database);
    }
    return task;
  }

  if (command === "delete") {
    const parsed = parseOptions(rest, new Set());
    if (parsed.positionals.length !== 1) fail("delete requires exactly one ID");
    const id = parseId(parsed.positionals[0]);
    const database = await loadDatabase(file);
    const index = database.tasks.findIndex((task) => task.id === id);
    if (index === -1) fail(`Task ${id} not found`);
    const [task] = database.tasks.splice(index, 1);
    await saveDatabase(file, database);
    return task;
  }

  if (command === "stats") {
    requireNoArguments(command, rest);
    const database = await loadDatabase(file);
    const today = localDate();
    const open = database.tasks.filter((task) => task.status === "open");
    return {
      total: database.tasks.length,
      open: open.length,
      done: database.tasks.length - open.length,
      overdue: open.filter((task) => task.due !== undefined && task.due < today)
        .length,
    };
  }

  fail(`Unknown command: ${command}`);
}

async function main(): Promise<void> {
  const configuredFile = process.env.TASKBOARD_FILE;
  const file = resolve(configuredFile || ".taskboard.json");
  try {
    const result = await execute(process.argv.slice(2), file);
    process.stdout.write(`${JSON.stringify(result)}\n`);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stdout.write(`${JSON.stringify({ error: message })}\n`);
    process.stderr.write(`taskboard: ${message}\n`);
    process.exitCode = 1;
  }
}

await main();

